from flask import Flask, jsonify
import json
app = Flask(__name__)
TOPICS = [{'grade': 6, 'title': 'To be', 'formula': 'S + am/is/are + ...', 'example': 'I am a student. / She is kind.', 'note': 'I → am; he/she/it → is; you/we/they → are.'}, {'grade': 6, 'title': 'Hiện tại đơn', 'formula': "(+) S + V(s/es); (-) S + don't/doesn't + V; (?) Do/Does + S + V?", 'example': 'He plays football. / Does she study English?', 'note': 'He/she/it thêm -s/-es ở câu khẳng định; sau does dùng V nguyên mẫu.'}, {'grade': 6, 'title': 'Hiện tại tiếp diễn', 'formula': 'S + am/is/are + V-ing', 'example': 'They are studying now.', 'note': 'Diễn tả việc đang diễn ra; thường gặp now, at the moment.'}, {'grade': 6, 'title': 'There is / There are', 'formula': 'There is + danh từ số ít; There are + danh từ số nhiều', 'example': 'There is a book. / There are two pens.', 'note': 'Câu hỏi: Is there...? / Are there...?'}, {'grade': 6, 'title': "Can / can't", 'formula': "S + can/can't + V nguyên mẫu", 'example': 'I can swim.', 'note': 'Không thêm to hoặc -s sau can.'}, {'grade': 6, 'title': 'Tính từ sở hữu', 'formula': 'my, your, his, her, its, our, their + danh từ', 'example': 'This is my bag.', 'note': 'Tính từ sở hữu đứng trước danh từ.'}, {'grade': 6, 'title': 'How much / How many', 'formula': 'How much + danh từ không đếm được?; How many + danh từ đếm được số nhiều?', 'example': 'How much water? / How many books?', 'note': 'Water không đếm được; books đếm được.'}, {'grade': 7, 'title': 'Quá khứ đơn', 'formula': "(+) S + V2/ed; (-) S + didn't + V; (?) Did + S + V?", 'example': 'We visited Hue. / Did you go?', 'note': "Sau did/didn't dùng động từ nguyên mẫu."}, {'grade': 7, 'title': 'Quá khứ của to be', 'formula': "S + was/were; wasn't/weren't; Was/Were + S...?", 'example': 'I was tired. / They were happy.', 'note': 'I/he/she/it → was; you/we/they → were.'}, {'grade': 7, 'title': 'Tương lai đơn', 'formula': "S + will/won't + V nguyên mẫu", 'example': 'I think it will rain.', 'note': 'Dùng cho dự đoán, quyết định hoặc lời hứa.'}, {'grade': 7, 'title': 'So sánh hơn', 'formula': 'adj ngắn-er + than; more + adj dài + than', 'example': 'taller than; more beautiful than', 'note': 'good → better; bad → worse.'}, {'grade': 7, 'title': "Should / shouldn't", 'formula': "S + should/shouldn't + V nguyên mẫu", 'example': 'You should rest.', 'note': 'Dùng đưa lời khuyên; không thêm to.'}, {'grade': 7, 'title': 'Lượng từ', 'formula': 'a few/few + danh từ đếm được; a little/little + không đếm được', 'example': 'a few friends; a little water', 'note': 'a few/a little = có một ít; few/little = rất ít.'}, {'grade': 8, 'title': 'Hiện tại đơn và tiếp diễn (HKI)', 'formula': 'S + V(s/es) / S + am-is-are + V-ing', 'example': 'She walks daily. / She is walking now.', 'note': 'Phân biệt thói quen với việc đang diễn ra.'}, {'grade': 8, 'title': 'Quá khứ đơn (HKI)', 'formula': "S + V2/ed; didn't + V; Did + S + V?", 'example': 'They watched a film yesterday.', 'note': 'Dùng cho việc đã hoàn tất trong quá khứ.'}, {'grade': 8, 'title': 'Will và be going to (HKI)', 'formula': 'will + V; am/is/are going to + V', 'example': 'I will help. / It is going to rain.', 'note': 'Be going to thường nói dự định hoặc dự đoán có căn cứ.'}, {'grade': 8, 'title': 'So sánh (HKI)', 'formula': 'adj-er/more + adj + than; as + adj + as', 'example': 'faster than; as tall as', 'note': 'Chọn dạng theo tính từ/trạng từ và ý nghĩa câu.'}, {'grade': 8, 'title': "Should, must, mustn't, have to (HKI)", 'formula': 'modal + V nguyên mẫu', 'example': 'You must wear a helmet.', 'note': "mustn't = không được phép; don't have to = không cần."}, {'grade': 8, 'title': 'Câu hỏi Wh- và Yes/No (HKI)', 'formula': 'Wh-word + trợ động từ + S + V?; Do/Does/Did + S + V?', 'example': 'Where do you live? / Did you go?', 'note': 'Với to be, đảo am/is/are/was/were lên trước chủ ngữ.'}, {'grade': 8, 'title': 'Liên từ (HKI)', 'formula': 'and = và; but = nhưng; because = bởi vì; so = vì vậy; although = mặc dù', 'example': 'I was tired, so I slept.', 'note': 'Chọn liên từ theo quan hệ nghĩa.'}, {'grade': 8, 'title': 'Đề nghị và lời mời (HKI)', 'formula': "Let's + V; Why don't we + V?; Would you like to + V?", 'example': "Let's play. / Would you like to join us?", 'note': "Sau Let's / Why don't we dùng V nguyên mẫu."}]
QUESTIONS = [{'grade': 6, 'q': 'My sister ___ a student.', 'opts': ['am', 'is', 'are', 'be'], 'a': 1, 'why': 'Số ít ngôi thứ ba dùng is.'}, {'grade': 6, 'q': 'Nam ___ to school every day.', 'opts': ['go', 'goes', 'going', 'is go'], 'a': 1, 'why': 'Hiện tại đơn: Nam = he, nên goes.'}, {'grade': 6, 'q': 'Look! They ___ football.', 'opts': ['play', 'plays', 'are playing', 'played'], 'a': 2, 'why': 'Look! gợi ý hành động đang diễn ra.'}, {'grade': 6, 'q': 'There ___ three chairs in the room.', 'opts': ['is', 'are', 'am', 'be'], 'a': 1, 'why': 'Three chairs là danh từ số nhiều.'}, {'grade': 6, 'q': 'I ___ ride a bike.', 'opts': ['can', 'am', 'does', 'did'], 'a': 0, 'why': 'Can + động từ nguyên mẫu.'}, {'grade': 7, 'q': 'We ___ our aunt last weekend.', 'opts': ['visit', 'visits', 'visited', 'visiting'], 'a': 2, 'why': 'Last weekend → quá khứ đơn.'}, {'grade': 7, 'q': '___ you see him yesterday?', 'opts': ['Do', 'Does', 'Did', 'Are'], 'a': 2, 'why': 'Câu hỏi quá khứ đơn dùng Did + S + V.'}, {'grade': 7, 'q': 'This bag is ___ than mine.', 'opts': ['heavy', 'heavier', 'heaviest', 'more heavy'], 'a': 1, 'why': 'Heavy đổi y thành i rồi thêm -er.'}, {'grade': 7, 'q': 'You ___ eat more vegetables.', 'opts': ['should', "shouldn't", "mustn't", 'did'], 'a': 0, 'why': 'Should dùng đưa lời khuyên.'}, {'grade': 7, 'q': 'I think it ___ be sunny tomorrow.', 'opts': ['will', 'was', 'does', 'has'], 'a': 0, 'why': 'Will thường dùng cho dự đoán tương lai.'}, {'grade': 8, 'q': 'If it ___ tomorrow, we will stay home.', 'opts': ['rains', 'will rain', 'rained', 'is rain'], 'a': 0, 'why': 'Mệnh đề If loại 1 dùng hiện tại đơn.'}, {'grade': 8, 'q': 'You ___ wear a helmet when riding a motorbike.', 'opts': ['must', "mustn't", "don't have", "shouldn't to"], 'a': 0, 'why': 'Must diễn tả sự bắt buộc.'}, {'grade': 8, 'q': 'I was tired, ___ I went to bed early.', 'opts': ['because', 'but', 'so', 'although'], 'a': 2, 'why': 'So nối nguyên nhân với kết quả.'}, {'grade': 8, 'q': 'Would you like ___ badminton with us?', 'opts': ['play', 'playing', 'to play', 'played'], 'a': 2, 'why': 'Would you like + to V.'}, {'grade': 8, 'q': 'This road is ___ than the old one.', 'opts': ['wide', 'wider', 'widest', 'more wide'], 'a': 1, 'why': 'Wide là tính từ ngắn, dùng wider.'}, {'grade': 8, 'q': 'Listen! Someone ___ at the door.', 'opts': ['knocks', 'is knocking', 'knocked', 'will knock'], 'a': 1, 'why': 'Listen! gợi ý hành động đang diễn ra.'}, {'grade': 8, 'q': 'Although it was cold, we ___ outside.', 'opts': ['played', 'play', 'playing', 'will played'], 'a': 0, 'why': 'Ngữ cảnh quá khứ dùng played.'}]
HTML = '<!doctype html>\n<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>English Grammar Hub</title>\n<style>\n:root{--bg:#0b1020;--panel:#151f36;--line:#30405f;--txt:#edf3ff;--muted:#aebbd5;--accent:#7ce6c7;--blue:#84aaff;--bad:#ff8795}\n*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top,#1c2a4b,#0b1020 60%);color:var(--txt);font:16px/1.55 system-ui,Arial}header{text-align:center;padding:28px 16px 16px}h1{font-size:clamp(28px,5vw,43px);margin:8px 0}header p{color:var(--muted);max-width:720px;margin:auto}.wrap{max-width:1000px;margin:auto;padding:0 14px 40px}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.tabs button,.btn{background:#1d2b49;border:1px solid var(--line);color:var(--txt);padding:10px 13px;border-radius:12px;font-weight:700;cursor:pointer}.tabs button.active,.primary{background:var(--accent)!important;color:#10231e!important}.panel{background:var(--panel);border:1px solid var(--line);border-radius:17px;padding:17px;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px}.tag{display:inline-block;border-radius:20px;background:#263756;color:var(--accent);padding:3px 9px;font-size:12px;font-weight:800}.formula{padding:12px;border-radius:11px;background:#0c1428;border:1px solid #304363;font-weight:750;margin:10px 0}.muted{color:var(--muted)}.example{color:#c8d7ff}.hide{display:none}.search{width:100%;padding:12px;border-radius:11px;border:1px solid var(--line);background:#0c1428;color:white;margin:8px 0}.option{display:block;width:100%;text-align:left;margin:8px 0;padding:12px;background:#0f192e;border:1px solid var(--line);border-radius:11px;color:var(--txt);cursor:pointer}.correct{border-color:var(--accent)!important;background:#16352f!important}.wrong{border-color:var(--bad)!important;background:#3b202c!important}.feedback{padding:12px;background:#0c1428;border-radius:10px;margin-top:12px}footer{text-align:center;color:var(--muted);padding:20px;font-size:13px}@media(max-width:500px){.panel{padding:13px}.tabs button{flex:1}}\n</style></head><body><header><span class="tag">LỚP 6 • LỚP 7 • LỚP 8 HKI</span><h1>English Grammar Hub</h1><p>Công thức tiếng Anh, ví dụ, ghi nhớ và bài tập trắc nghiệm. Nội dung lớp 8 tập trung học kì I; thứ tự/chủ điểm có thể khác tùy bộ sách.</p></header>\n<div class="wrap"><div class="tabs"><button class="active" onclick="tab(\'formulas\',this)">📘 Công thức</button><button onclick="tab(\'practice\',this)">🎯 Luyện tập</button><button onclick="tab(\'exam\',this)">📝 Kiểm tra nhanh</button></div>\n<section id="formulas"><div class="panel"><h2>Tra cứu công thức</h2><input id="search" class="search" placeholder="Tìm công thức..." oninput="renderTopics()"><div class="tabs" id="filters"><button class="active" onclick="setGrade(0,this)">Tất cả</button><button onclick="setGrade(6,this)">Lớp 6</button><button onclick="setGrade(7,this)">Lớp 7</button><button onclick="setGrade(8,this)">Lớp 8 HKI</button></div><div id="topicList" class="grid"></div></div></section>\n<section id="practice" class="hide"><div class="panel"><h2>Luyện tập</h2><div class="tabs" id="pfilters"><button class="active" onclick="setPGrade(0,this)">Tất cả</button><button onclick="setPGrade(6,this)">Lớp 6</button><button onclick="setPGrade(7,this)">Lớp 7</button><button onclick="setPGrade(8,this)">Lớp 8 HKI</button></div><p id="progress" class="muted"></p><div id="quiz"></div><button class="btn primary" onclick="nextQ()">Câu tiếp theo →</button><p id="score" class="muted"></p></div></section>\n<section id="exam" class="hide"><div class="panel"><h2>Kiểm tra nhanh</h2><p>Chọn phạm vi để làm bài ngẫu nhiên.</p><div class="tabs"><button onclick="startExam(0)">Tất cả</button><button onclick="startExam(6)">Lớp 6</button><button onclick="startExam(7)">Lớp 7</button><button onclick="startExam(8)">Lớp 8 HKI</button></div><div id="examArea"></div></div></section><footer>English Grammar Hub • Học đều mỗi ngày một ít ✨</footer></div>\n<script>\nconst topics=__TOPICS__, questions=__QUESTIONS__;let grade=0,pg=0,current=null,done=false,score=0,total=0,exam=[],ei=0,es=0;\nfunction esc(s){return String(s).replace(/[&<>"]/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\'}[c]))}\nfunction tab(id,b){document.querySelectorAll(\'section\').forEach(s=>s.classList.add(\'hide\'));document.getElementById(id).classList.remove(\'hide\');document.querySelectorAll(\'.wrap>.tabs button\').forEach(x=>x.classList.remove(\'active\'));b.classList.add(\'active\')}\nfunction setGrade(g,b){grade=g;document.querySelectorAll(\'#filters button\').forEach(x=>x.classList.remove(\'active\'));b.classList.add(\'active\');renderTopics()}\nfunction renderTopics(){let s=document.getElementById(\'search\').value.toLowerCase();let arr=topics.filter(t=>(!grade||t.grade===grade)&&[t.title,t.formula,t.example,t.note].join(\' \').toLowerCase().includes(s));document.getElementById(\'topicList\').innerHTML=arr.map(t=>`<article class="panel"><span class="tag">LỚP ${t.grade}${t.grade===8?\' • HKI\':\'\'}</span><h3>${esc(t.title)}</h3><div class="formula">${esc(t.formula)}</div><p class="example"><b>Ví dụ:</b> ${esc(t.example)}</p><p class="muted"><b>Ghi nhớ:</b> ${esc(t.note)}</p></article>`).join(\'\')||\'<p>Không tìm thấy công thức.</p>\'}\nfunction setPGrade(g,b){pg=g;document.querySelectorAll(\'#pfilters button\').forEach(x=>x.classList.remove(\'active\'));b.classList.add(\'active\');score=0;total=0;nextQ()}\nfunction pool(){return questions.filter(q=>!pg||q.grade===pg)}\nfunction nextQ(){let p=pool();current=p[Math.floor(Math.random()*p.length)];done=false;document.getElementById(\'progress\').textContent=\'Đã trả lời \'+total+\' câu\';document.getElementById(\'quiz\').innerHTML=`<span class="tag">LỚP ${current.grade}${current.grade===8?\' • HKI\':\'\'}</span><h3>${esc(current.q)}</h3>${current.opts.map((o,i)=>`<button class="option" onclick="answer(${i},this)">${\'ABCD\'[i]}. ${esc(o)}</button>`).join(\'\')}<div id="feedback"></div>`;document.getElementById(\'score\').textContent=`Điểm: ${score}/${total}`}\nfunction answer(i){if(done)return;done=true;total++;let ok=i===current.a;if(ok)score++;document.querySelectorAll(\'#quiz .option\').forEach((b,j)=>{if(j===current.a)b.classList.add(\'correct\');if(j===i&&!ok)b.classList.add(\'wrong\')});document.getElementById(\'feedback\').innerHTML=`<div class="feedback"><b>${ok?\'✅ Chính xác!\':\'❌ Chưa đúng.\'}</b><br>Đáp án: ${\'ABCD\'[current.a]}. ${esc(current.opts[current.a])}<br><span class="muted">${esc(current.why)}</span></div>`;document.getElementById(\'score\').textContent=`Điểm: ${score}/${total}`}\nfunction startExam(g){let p=questions.filter(q=>!g||q.grade===g).sort(()=>Math.random()-.5);exam=p.slice(0,Math.min(10,p.length));ei=0;es=0;showExam()}\nfunction showExam(){if(ei>=exam.length){document.getElementById(\'examArea\').innerHTML=`<h3>Hoàn thành!</h3><p>Bạn đúng ${es}/${exam.length} câu.</p><button class="btn primary" onclick="startExam(0)">Làm lại</button>`;return}let q=exam[ei];document.getElementById(\'examArea\').innerHTML=`<p class="muted">Câu ${ei+1}/${exam.length}</p><h3>${esc(q.q)}</h3>${q.opts.map((o,i)=>`<button class="option" onclick="examAnswer(${i})">${\'ABCD\'[i]}. ${esc(o)}</button>`).join(\'\')}`}\nfunction examAnswer(i){let q=exam[ei];if(i===q.a)es++;document.querySelectorAll(\'#examArea .option\').forEach((b,j)=>{b.disabled=true;if(j===q.a)b.classList.add(\'correct\');if(j===i&&i!==q.a)b.classList.add(\'wrong\')});let p=document.createElement(\'p\');p.className=\'feedback\';p.textContent=q.why;document.getElementById(\'examArea\').appendChild(p);let b=document.createElement(\'button\');b.className=\'btn primary\';b.textContent=\'Tiếp theo →\';b.onclick=()=>{ei++;showExam()};document.getElementById(\'examArea\').appendChild(b)}\nrenderTopics();nextQ();\n</script></body></html>'
@app.route("/")
def home():
    page = HTML.replace("__TOPICS__", json.dumps(TOPICS, ensure_ascii=False)).replace("__QUESTIONS__", json.dumps(QUESTIONS, ensure_ascii=False))
    return page
@app.route("/health")
def health():
    return jsonify(status="ok", app="English Grammar Hub", topics=len(TOPICS), questions=len(QUESTIONS))
if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=False)
